/**
 * Activity and interest catalogue rules, shared by onboarding, profile edit and meetup setup.
 *
 * - Only child rows can be picked. A parent (a row with no parent) is a section header and is never
 *   selectable, saved or shown as a chip. The database enforces the same rule with triggers.
 * - Search matches child names only, never a parent's name. A group keeps its header while it has matches.
 * - "Your activities" comes first when given, and those rows aren't repeated under their parent.
 */

export type CatalogKind = 'activity' | 'interest';

export type CatalogParent = { slug?: string | null; name: string; sort_order: number };

export type CatalogItem = {
  id: string;
  slug?: string;
  name: string;
  kind?: CatalogKind | null;
  sort_order: number;
  parent_id?: string | null;
  parent?: CatalogParent | null;
  show_in_onboarding?: boolean | null;
  onboarding_sort?: number | null;
};

export type CatalogGroup<T extends CatalogItem> = { key: string; label: string; items: T[] };

export const YOUR_ACTIVITIES_KEY = 'mine';

/** A child has a parent. Rows without one are parent groups. */
export function isSelectable(item: CatalogItem): boolean {
  return Boolean(item.parent_id || item.parent);
}

export function kindOf(item: CatalogItem): CatalogKind {
  return item.kind === 'interest' ? 'interest' : 'activity';
}

function byOrder<T extends CatalogItem>(order: (item: T) => number) {
  return (a: T, b: T) => order(a) - order(b) || a.name.localeCompare(b.name);
}

function groupKey(item: CatalogItem) {
  return item.parent?.slug || item.parent?.name || item.parent_id || 'other';
}

/** Buckets children under their parent, groups in parent order, rows in `itemOrder`. Empty groups never appear. */
function bucket<T extends CatalogItem>(items: T[], itemOrder: (item: T) => number): CatalogGroup<T>[] {
  const groups = new Map<string, { order: number; group: CatalogGroup<T> }>();
  for (const item of items) {
    const key = groupKey(item);
    const entry = groups.get(key) ?? { order: item.parent?.sort_order ?? 9999, group: { key, label: item.parent?.name ?? '', items: [] } };
    entry.group.items.push(item);
    groups.set(key, entry);
  }
  return [...groups.values()]
    .sort((a, b) => a.order - b.order || a.group.label.localeCompare(b.group.label))
    .map(({ group }) => ({ ...group, items: [...group.items].sort(byOrder(itemOrder)) }));
}

/** Child names only: "yoga" finds Yoga; "sports" does not return the Sports & fitness group. */
export function matchesQuery(item: CatalogItem, query: string): boolean {
  const needle = query.trim().toLowerCase();
  return !needle || item.name.toLowerCase().includes(needle);
}

/**
 * The full catalogue for one kind, grouped by parent, with search (profile edit and meetup sheets).
 * `mineIds` puts the user's saved activities first under `yourLabel`, and leaves them out of their parent group.
 */
export function catalogGroups<T extends CatalogItem>(
  items: T[],
  options: { kind: CatalogKind; query?: string; mineIds?: readonly string[]; yourLabel?: string },
): CatalogGroup<T>[] {
  const query = options.query ?? '';
  const children = items.filter((item) => isSelectable(item) && kindOf(item) === options.kind && matchesQuery(item, query));
  const mine = new Set(options.kind === 'activity' ? (options.mineIds ?? []) : []);
  const yours = children.filter((item) => mine.has(item.id)).sort(byOrder((item) => item.sort_order));
  const rest = bucket(
    children.filter((item) => !mine.has(item.id)),
    (item) => item.sort_order,
  );
  return yours.length ? [{ key: YOUR_ACTIVITIES_KEY, label: options.yourLabel ?? 'Your activities', items: yours }, ...rest] : rest;
}

/** Onboarding step 1: only the flagged activities, grouped by parent, in onboarding order. */
export function onboardingActivityGroups<T extends CatalogItem>(items: T[]): CatalogGroup<T>[] {
  return bucket(
    items.filter((item) => isSelectable(item) && kindOf(item) === 'activity' && item.show_in_onboarding),
    (item) => item.onboarding_sort ?? item.sort_order,
  );
}

/** Onboarding step 2: every interest, grouped by parent. Groups without interests are left out. */
export function onboardingInterestGroups<T extends CatalogItem>(items: T[]): CatalogGroup<T>[] {
  return catalogGroups(items, { kind: 'interest' });
}

/** How many of `ids` are of `kind` (for "Next · N picked"). */
export function countPicked(items: CatalogItem[], ids: readonly string[], kind: CatalogKind): number {
  const wanted = new Set(items.filter((item) => isSelectable(item) && kindOf(item) === kind).map((item) => item.id));
  return ids.filter((id) => wanted.has(id)).length;
}

/**
 * The ids that may be saved: children in the catalogue only, no duplicates. Anything else (a parent, a stale id)
 * is dropped, so a parent can never reach the API.
 */
export function selectableIds(items: CatalogItem[], ids: readonly string[]): string[] {
  const allowed = new Set(items.filter(isSelectable).map((item) => item.id));
  return [...new Set(ids)].filter((id) => allowed.has(id));
}
